 void input(int mode,int idx=-1){if(root.empty()){chooseRoot();if(root.empty())return;}editMode=mode;editIndex=idx;draftAccent=mode==4?boards.at(idx).accent:0x8889cb;std::wstring value=mode==1?L"":mode==4?boards.at(idx).name:mode==2?board().name:photo(idx).name;WNDCLASSW cls{};cls.lpfnWndProc=editHostProc;cls.hInstance=instance;cls.lpszClassName=L"HuahuaEditSurface";cls.hCursor=LoadCursor(nullptr,IDC_ARROW);RegisterClassW(&cls);editHost=CreateWindowExW(WS_EX_TOOLWINDOW,L"HuahuaEditSurface",L"",WS_POPUP|WS_CLIPCHILDREN,0,0,400,32,hwnd,nullptr,instance,nullptr);edit=CreateWindowExW(0,L"EDIT",value.c_str(),WS_CHILD|WS_VISIBLE|ES_AUTOHSCROLL|ES_NOHIDESEL,0,0,400,32,editHost,(HMENU)500,instance,nullptr);if(!editHost||!edit){if(editHost)DestroyWindow(editHost);editHost=edit=nullptr;throw std::runtime_error("无法创建名称输入框");}editNeedsSelection=true;SendMessageW(edit,EM_SETLIMITTEXT,90,0);SendMessageW(edit,EM_SETCUEBANNER,TRUE,(LPARAM)L"输入名字");if(editFont)DeleteObject(editFont);editFont=CreateFontW(-int(16*dpi/96),0,0,0,FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH,uiFont.c_str());SendMessageW(edit,WM_SETFONT,(WPARAM)editFont,TRUE);InvalidateRect(hwnd,nullptr,FALSE);}
 void finishInput(bool accept){if(!edit)return;std::wstring oldBoardName=editMode==4?boards.at(editIndex).name:board().name;wchar_t txt[256];GetWindowTextW(edit,txt,256);DestroyWindow(editHost);editHost=edit=nullptr;editNeedsSelection=false;SetFocus(hwnd);if(accept&&*txt){if(editMode==1){boards.push_back({uid(),cleanName(txt),draftAccent,{}});active=boards.size()-1;boardPage=active/boardRows();scroll=targetScroll=0;panel=0;}else if(editMode==4){boards.at(editIndex).name=cleanName(txt);boards.at(editIndex).accent=draftAccent;}else if(editMode==2)board().name=cleanName(txt);else if(editIndex>=0&&editIndex<(int)board().photos.size()){auto&p=photo(editIndex);Photo previous=p;auto old=root/p.file;auto newPath=old.parent_path()/(cleanName(txt)+L"_"+wide(uid().substr(0,8))+old.extension().wstring());bool moved=false;try{if(!save())throw std::runtime_error("请先解决保存失败");fs::rename(old,newPath);moved=true;p.name=cleanName(txt);p.file=fs::relative(newPath,root).wstring();changed();if(!save())throw std::runtime_error("名称未保存");}catch(const std::exception&e){if(moved){std::error_code ec;fs::rename(newPath,old,ec);if(ec)toast(L"回滚失败，请检查文件位置");}p=previous;changed();error(e.what());}}changed();if(editMode==1)syncBoardFolder(active);else if(editMode==4)syncBoardFolder(editIndex,oldBoardName!=boards.at(editIndex).name);else if(editMode==2)syncBoardFolder(active,oldBoardName!=board().name);relayout(true);}InvalidateRect(hwnd,nullptr,FALSE);}
 void importPaths(const std::vector<fs::path>&paths){if(modalOpen)return;if(root.empty()){chooseRoot();if(root.empty())return;}if(!syncBoardFolder(active))return;int ok=0,skip=0;IWICImagingFactory*w=nullptr;CoCreateInstance(CLSID_WICImagingFactory,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&w));SetCursor(LoadCursor(nullptr,IDC_ARROW));for(auto&p:paths){try{if(!fs::is_regular_file(p)){skip++;continue;}auto ext=p.extension().wstring();std::transform(ext.begin(),ext.end(),ext.begin(),towlower);if(ext!=L".png"&&ext!=L".jpg"&&ext!=L".jpeg"&&ext!=L".bmp"&&ext!=L".gif"&&ext!=L".tif"&&ext!=L".tiff"&&ext!=L".webp"){skip++;continue;}if(fs::file_size(p)>150ull*1024*1024){skip++;continue;}auto id=uid();std::unique_ptr<Pixels>test(w?decode(w,{id,p,32}):nullptr);if(!test||test->bytes.empty()){skip++;continue;}auto dir=root/L"图片"/board().folder;fs::create_directories(dir);auto name=cleanName(p.stem().wstring());auto dest=dir/(name+L"_"+wide(id.substr(0,8))+ext);fs::copy_file(p,dest);board().photos.push_back({id,name,fs::relative(dest,root).wstring(),test->ratio});ok++;}catch(const std::exception&){skip++;}}release(w);SetCursor(LoadCursor(nullptr,IDC_ARROW));if(ok){changed();save();relayout(true);}toast(L"已添加 "+std::to_wstring(ok)+L" 张"+(skip?L" · "+std::to_wstring(skip)+L" 个未支持或读取失败":L""));}
 void importDialog(){if(root.empty()){chooseRoot();if(root.empty())return;}IFileOpenDialog*d=nullptr;if(SUCCEEDED(CoCreateInstance(CLSID_FileOpenDialog,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&d)))){DWORD o;d->GetOptions(&o);d->SetOptions(o|FOS_ALLOWMULTISELECT|FOS_FORCEFILESYSTEM|FOS_FILEMUSTEXIST);COMDLG_FILTERSPEC f[]={{L"图片",L"*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.tif;*.tiff;*.webp"}};d->SetFileTypes(1,f);d->SetTitle(L"添加图片");if(SUCCEEDED(d->Show(hwnd))){IShellItemArray*a=nullptr;d->GetResults(&a);DWORD count=0;if(a)a->GetCount(&count);std::vector<fs::path>paths;for(DWORD i=0;i<count;i++){IShellItem*s=nullptr;a->GetItemAt(i,&s);PWSTR p=nullptr;if(s&&SUCCEEDED(s->GetDisplayName(SIGDN_FILESYSPATH,&p))){paths.emplace_back(p);CoTaskMemFree(p);}release(s);}release(a);importPaths(paths);}release(d);}}
 void action(int a,int arg=0){switch(a){case 80:dismissModal(false);break;case 81:dismissModal(true);break;case 82:undoDelete();break;case 1:case 2:case 3:if(a==3)refreshRecycle();if(panel!=a){lastPanel=a;indicator.set(float(a-1),clock(),.35);}panel=panel==a?0:a;break;case 4:panel=0;break;case 10:panel=0;importDialog();break;case 11:chooseRoot();break;case 12:if(!root.empty())ShellExecuteW(hwnd,L"open",(root/L"图片").c_str(),nullptr,nullptr,SW_SHOWNORMAL);break;case 13:if(save())toast(L"已保存");break;case 20:selected.clear();active=arg;scroll=targetScroll=0;viewer=-1;panel=0;changed();relayout(true);break;case 21:input(1);break;case 22:input(4,active);break;case 25:input(4,arg);break;case 23:boardPage=std::max(0,boardPage-1);break;case 24:boardPage=std::min(int((boards.size()-1)/boardRows()),boardPage+1);break;case 30:columns=std::max(1,columns-1);changed();relayout();break;case 31:columns=std::min(8,columns+1);changed();relayout();break;case 32:viewFraction=std::max(.35f,viewFraction-.08f);changed();relayout();break;case 33:viewFraction=std::min(.88f,viewFraction+.08f);changed();relayout();break;case 34:board().accent=arg;changed();break;case 36:sliderDrag=1;slide(mouseX);SetCapture(hwnd);break;case 37:sliderDrag=2;slide(mouseX);SetCapture(hwnd);break;case 35:motion=!motion;changed();break;case 40:input(3,arg);break;case 50:viewer=-1;pendingViewer=-1;resetZoom();break;case 51:switchViewer((pendingViewer>=0?pendingViewer:viewer)-1);break;case 52:switchViewer((pendingViewer>=0?pendingViewer:viewer)+1);break;case 60:finishInput(false);break;case 61:finishInput(true);break;case 62:draftAccent=arg;break;case 63:removeBoard(editIndex);break;case 64:clearBoard(editIndex);break;case 65:deleteSelected();break;case 66:selected.clear();break;case 67:{int i=editIndex;finishInput(false);remove(i);}break;case 14:openRecycle();break;}InvalidateRect(hwnd,nullptr,FALSE);}
 void updateDropTarget(){dropTarget=swapTarget(drawn,canvas,scroll,mouseX,mouseY,down);}
 int photoAt(float x,float y){if(!canvas.contains(x,y))return -1;for(int i=0;i<(int)drawn.size();i++)if(visible(i).contains(x,y))return i;return -1;}
 void move(float x,float y){mouseX=x;mouseY=y;if(modalOpen){InvalidateRect(hwnd,nullptr,FALSE);return;}updateCursor(x,y);if(panning&&viewer>=0){panX+=x-panMouseX;panY+=y-panMouseY;panMouseX=x;panMouseY=y;clampPan();InvalidateRect(hwnd,nullptr,FALSE);return;}if(thumbDragging){scroll=targetScroll=std::clamp((y-thumbOffset-scrollTrack.y)/std::max(1.f,scrollTrack.h-scrollThumb.h),0.f,1.f)*maxScroll;InvalidateRect(hwnd,nullptr,FALSE);return;}if(sliderDrag){slide(x);return;}if(resizing){animateWidth(std::clamp(2*std::abs(x-W/2),340.f,std::max(340.f,W-224)));}if(down>=0&&!dragging&&std::hypot(x-downX,y-downY)>7)dragging=true;if(dragging)updateDropTarget();hover=photoAt(x,y);InvalidateRect(hwnd,nullptr,FALSE);}
 void clickDown(float x,float y){mouseX=x;mouseY=y;if(modalOpen){for(auto it=hits.rbegin();it!=hits.rend();it++)if((it->action==80||it->action==81)&&it->b.contains(x,y)){action(it->action);return;}return;}for(auto&hit:hits)if(hit.action==82&&hit.b.contains(x,y)){undoDelete();return;}if(edit){for(auto it=hits.rbegin();it!=hits.rend();it++)if(it->action>=60&&it->action<=67&&it->b.contains(x,y)){action(it->action,it->arg);return;}return;}SetFocus(hwnd);if(!panel&&viewer<0&&(GetKeyState(VK_SHIFT)&0x8000)){int i=photoAt(x,y);if(i>=0){auto id=photo(i).id;if(selected.count(id))selected.erase(id);else selected.insert(id);}down=-1;InvalidateRect(hwnd,nullptr,FALSE);return;}if(edge(x,y)){resizing=true;SetCapture(hwnd);InvalidateRect(hwnd,nullptr,FALSE);return;}if(viewer>=0){for(auto it=hits.rbegin();it!=hits.rend();it++)if(((it->action>=50&&it->action<=52)||it->action==40)&&it->b.contains(x,y)){action(it->action,it->arg);return;}if(viewerImage().contains(x,y)){if(zoom>1){panning=true;panMouseX=x;panMouseY=y;SetCapture(hwnd);updateCursor(x,y);}}else{viewer=-1;pendingViewer=-1;resetZoom();}InvalidateRect(hwnd,nullptr,FALSE);return;}for(auto it=hits.rbegin();it!=hits.rend();it++)if(it->b.contains(x,y)){if(panel&&(it->action==40||it->action>=70))continue;bool panelAction=it->action>=11&&it->action<=37;if(panel&&!panelBox.contains(x,y)&&panelAction)continue;if(!panel&&it->action!=10&&it->action!=11&&it->action>=11&&it->action<=37)continue;action(it->action,it->arg);return;}if(panel){panel=0;InvalidateRect(hwnd,nullptr,FALSE);return;}down=photoAt(x,y);downX=x;downY=y;dropTarget=-1;if(down>=0)SetCapture(hwnd);}
 void clickUp(){if(panning){panning=false;ReleaseCapture();updateCursor(mouseX,mouseY);return;}if(thumbDragging){thumbDragging=false;ReleaseCapture();return;}if(sliderDrag){sliderDrag=0;ReleaseCapture();InvalidateRect(hwnd,nullptr,FALSE);return;}if(resizing){resizing=false;ReleaseCapture();InvalidateRect(hwnd,nullptr,FALSE);return;}if(down<0)return;if(dragging){updateDropTarget();if(swapItems(board().photos,down,dropTarget)){swapItems(drawn,down,dropTarget);changed();relayout();}}else if(!dragging){viewer=down;pendingViewer=-1;resetZoom();viewerFade=0;panel=0;}down=-1;dragging=false;dropTarget=-1;ReleaseCapture();InvalidateRect(hwnd,nullptr,FALSE);}
 void wheel(float delta){if(edit||modalOpen)return;if(viewer>=0){float next=std::clamp(zoom*std::pow(1.15f,delta),1.f,8.f),k=next/zoom;panX=zoomPanOffset(panX,mouseX-W/2,k);panY=zoomPanOffset(panY,mouseY-H/2,k);zoom=next;clampPan();updateCursor(mouseX,mouseY);InvalidateRect(hwnd,nullptr,FALSE);return;}if(panel){if(panel==1){boardPage=std::clamp(boardPage+(delta<0?1:-1),0,int((boards.size()-1)/boardRows()));InvalidateRect(hwnd,nullptr,FALSE);}return;}targetScroll=std::clamp(targetScroll-delta*80,0.f,maxScroll);}
 bool sampleLayout(double tm){bool movingLayout=layoutTween.update(tm,motion);for(size_t i=0;i<drawn.size()&&i<layout.size()&&i<layoutFrom.size();i++){auto a=layoutFrom[i],b=layout[i];float t=layoutTween.value;drawn[i]={a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t,(resizing||sliderDrag==2)?b.w:a.w+(b.w-a.w)*t,(resizing||sliderDrag==2)?b.h:a.h+(b.h-a.h)*t};if(resizing||sliderDrag==2){float inset=W<=700?22:30;drawn[i].x=std::clamp(drawn[i].x,canvas.x+inset,std::max(canvas.x+inset,canvas.x+canvas.w-inset-drawn[i].w));}}return movingLayout;}
 void tick(){auto now=GetTickCount64();double stamp=clock();float dt=std::min(.05f,float(stamp-lastFrame));lastFrame=stamp;lastTick=now;bool animate=modalOpen&&modalTween.update(stamp,motion);if(widthDirty){sampleLayout(stamp);widthDirty=false;canvasWidth=displayedWidth=pendingWidth;canvasMoving=false;relayout();animate=true;}auto step=[&](float&v,float t){if(!motion){if(v!=t){v=t;animate=true;}return;}if(std::abs(v-t)>.001f){v=approach(v,t,dt);animate=true;}else if(v!=t){v=t;animate=true;}};step(scroll,targetScroll);double tm=clock();for(int i=0;i<3;i++){auto&t=viewerHover[i];float target=viewer>=0&&!edit&&!panning&&viewerButton(i).contains(mouseX,mouseY)?1.f:0.f;if(t.to!=target)t.set(target,tm,target?.22:.30);float old=t.value;animate|=t.update(tm,motion);animate|=old!=t.value;}float addTarget=viewer<0&&!edit&&tool(3).contains(mouseX,mouseY)?1.f:0.f;if(addTween.to!=addTarget)addTween.set(addTarget,tm,addTarget?.55:.45);animate|=addTween.update(tm,motion);if(lastContent!=panel){lastContent=panel;contentTween.value=0;contentTween.set(1,tm,.22);}animate|=contentTween.update(tm,motion);if(panelTween.to!=(panel?1.f:0.f))panelTween.set(panel?1.f:0.f,tm,.30);if(viewer>=0&&viewerFade==0&&previewTween.value>0){previewTween.value=0;previewTween.set(1,tm,.25);}if(previewTween.to!=(viewer>=0?1.f:0.f))previewTween.set(viewer>=0?1.f:0.f,tm,.25);animate|=panelTween.update(tm,motion);animate|=previewTween.update(tm,motion);animate|=indicator.update(tm,motion);panelFade=panelTween.value;viewerFade=previewTween.value;animate|=sampleLayout(tm);if(dragging){updateDropTarget();if(mouseY<canvas.y+105)targetScroll=std::max(0.f,targetScroll-10);if(mouseY>canvas.y+canvas.h-60)targetScroll=std::min(maxScroll,targetScroll+10);animate=true;}checkSave();if(dirty&&now>saveDue&&!failedSave)autoSave();if(toastUntil&&now>toastUntil){toastUntil=0;animate=true;}frameActive=animate;if(animate)InvalidateRect(hwnd,nullptr,FALSE);}
 fs::path recycleRoot(){return root/L"图片"/L"回收站";}
 void refreshRecycle(){recycleBytes=0;if(root.empty())return;std::error_code ec;for(fs::recursive_directory_iterator i(recycleRoot(),fs::directory_options::skip_permission_denied,ec),end;i!=end;i.increment(ec)){if(ec)break;if(i->is_regular_file(ec)){auto n=i->file_size(ec);if(!ec)recycleBytes+=n;}}}
 void openRecycle(){if(root.empty())return;try{fs::create_directories(recycleRoot());ShellExecuteW(hwnd,L"open",recycleRoot().c_str(),nullptr,nullptr,SW_SHOWNORMAL);}catch(const std::exception&e){error(e.what());}}
 void deleteSelected(){std::vector<int> ids;for(int i=0;i<int(board().photos.size());i++)if(selected.count(photo(i).id))ids.push_back(i);recyclePhotos(active,ids,false);}
 void clearBoard(int i){if(i<0||i>=int(boards.size()))return;std::vector<int> ids;for(int n=0;n<int(boards[i].photos.size());n++)ids.push_back(n);recyclePhotos(i,ids,true);}
 void recyclePhotos(int bi,std::vector<int> ids,bool clearing,bool confirmed=false){if(ids.empty()){toast(L"没有需要删除的图片");return;}if(!confirmed&&(clearing||!recycleNotice)){showModal(clearing?L"清空图板？":L"移至回收站",{L"将移动 "+std::to_wstring(ids.size())+L" 张图片到 图片\\回收站。",L"文件仍占磁盘空间，原始导入文件不受影响。",L"可从资料库面板打开，删除后可撤销。"},[this,bi,ids,clearing]{recyclePhotos(bi,ids,clearing,true);});return;}performDelete(bi,ids,false);}
 void removeBoard(int i,bool confirmed=false){if(i<0||i>=int(boards.size()))return;if(!confirmed){showModal(L"删除图板？",{L"将其中的 "+std::to_wstring(boards[i].photos.size())+L" 张图片移至回收站。",L"图板文件夹会移除，图片仍占磁盘空间。",L"操作完成后可撤销。"},[this,i]{removeBoard(i,true);});return;}std::vector<int>ids;for(int n=0;n<int(boards[i].photos.size());n++)ids.push_back(n);performDelete(i,ids,true);}
 void performDelete(int bi,std::vector<int> ids,bool whole){if(!save())return;finishInput(false);auto before=boards;int was=active;auto folder=root/L"图片"/boards[bi].folder;std::vector<std::pair<fs::path,fs::path>> moved;try{fs::create_directories(recycleRoot());std::sort(ids.begin(),ids.end());ids.erase(std::unique(ids.begin(),ids.end()),ids.end());for(int i:ids){auto&p=before[bi].photos.at(i);auto old=root/p.file;auto next=availableName(recycleRoot(),p.name,old.extension().wstring());fs::rename(old,next);moved.push_back({old,next});}if(whole&&!boards[bi].folder.empty()&&fs::exists(folder)){for(auto&entry:fs::directory_iterator(folder)){if(!entry.is_regular_file())throw std::runtime_error("图板目录内有其他子文件夹，已取消删除");auto old=entry.path();auto next=availableName(recycleRoot(),old.stem().wstring(),old.extension().wstring());fs::rename(old,next);moved.push_back({old,next});}fs::remove(folder);}if(whole){boards.erase(boards.begin()+bi);if(boards.empty())boards.push_back({uid(),L"未命名",0x8889cb,{}});active=std::clamp(was-(bi<was?1:0),0,int(boards.size())-1);}else for(auto i=ids.rbegin();i!=ids.rend();++i)boards[bi].photos.erase(boards[bi].photos.begin()+*i);recycleNotice=true;changed();if(!save())throw std::runtime_error("删除记录保存失败");selected.clear();viewer=pendingViewer=hover=down=-1;panel=whole?1:0;boardPage=active/boardRows();relayout(true);refreshRecycle();rememberUndo(before,was,moved);}catch(const std::exception&e){boards=before;active=was;for(auto i=moved.rbegin();i!=moved.rend();++i){std::error_code ec;fs::create_directories(i->first.parent_path(),ec);fs::rename(i->second,i->first,ec);}dirty=true;error(e.what());}}
 void remove(int i){if(i>=0&&i<int(board().photos.size()))recyclePhotos(active,{i},false);}
 void key(WPARAM k){if(modalOpen){if(k==VK_ESCAPE)dismissModal(false);if(k==VK_RETURN)dismissModal(true);return;}if(k=='Z'&&(GetKeyState(VK_CONTROL)&0x8000)&&!edit){undoDelete();return;}if(edit){if(k==VK_RETURN)finishInput(true);if(k==VK_ESCAPE)finishInput(false);return;}if(k==VK_F12)debugFrames=!debugFrames;if(k==VK_ESCAPE){selected.clear();pendingViewer=-1;resetZoom();viewer=-1;panel=0;dragging=false;down=-1;ReleaseCapture();}if(k==VK_LEFT&&viewer>=0)action(51);if(k==VK_RIGHT&&viewer>=0)action(52);if(k==VK_F2){int i=viewer>=0?viewer:hover;if(i>=0)input(3,i);}if(k==VK_DELETE){if(viewer<0&&!selected.empty())deleteSelected();else remove(viewer>=0?viewer:hover);}if(k=='O'&&(GetKeyState(VK_CONTROL)&0x8000))importDialog();if(k=='S'&&(GetKeyState(VK_CONTROL)&0x8000)){if(save())toast(L"已保存");}if(k==VK_HOME)targetScroll=0;if(k==VK_END)targetScroll=maxScroll;if(k==VK_NEXT)targetScroll=std::min(maxScroll,targetScroll+H*.75f);if(k==VK_PRIOR)targetScroll=std::max(0.f,targetScroll-H*.75f);InvalidateRect(hwnd,nullptr,FALSE);}
